import{z as i,x as o,o as e,c as s,q as t,j as B,D as a,d as l,s as n,S as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"KV 与投机解码","description":"","frontmatter":{"title":"KV 与投机解码","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kv-speculative-interaction.md","filePath":"llm/kv-speculative-interaction.md","lastUpdated":1791413859000}'),p={name:"llm/kv-speculative-interaction.md"};function m(C,E,d,D,c,h){const A=o("Mermaid");return e(),s("div",null,[E[2]||(E[2]=t('<h1 id="kv-与投机解码" tabindex="-1">KV 与投机解码 <a class="header-anchor" href="#kv-与投机解码" aria-label="Permalink to &quot;KV 与投机解码&quot;">​</a></h1><div class="epigraph"><p>投机解码把一步变成一个接受长度可变的块；缓存侧的一切麻烦都来自同一件事——先写了，但还没被允许生效。</p><footer>—— 据 Leviathan et al., ICML 2023 的接受–拒绝结构整理</footer></div><p><a href="/llm/kv-longcontext-budget">上一课</a>把预算留了回滚余量，本课解释这笔余量付给谁。<a href="/llm/speculative-decoding">投机解码</a>让草稿先猜 \\(\\gamma\\) 个 token、目标一次并行校验；无损性由<a href="/llm/speculative-sampling">接受–拒绝规则</a>保证。但保证分布无损的是算法，缓存是有状态的：草稿 token 的 KV 已经写进页里，拒绝之后能不能干净地撤掉，决定了无损性在系统里是否兑现。本课写回滚协议、峰值预算与树分支的页管理。接受率怎么调、草稿怎么选不是本课主题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>被拒草稿的 KV 若留在缓存里，下一步的因果注意力会 attend 到这些键——<strong>模型看见了不存在的 token</strong>，分布从此漂移，投机承诺作废。这是正确性问题，不是空间浪费。第二个麻烦是预算：每条请求在校验期间多挂 \\(\\gamma\\) 个位置的临时 KV，满并发时池子峰值乘上 \\((1+\\gamma)\\) 因子；接受长度又是随机变量，预算若按均值编，坏运气的一拍就会触发抢占。第三个是树：<a href="/llm/speculative-tree">树状验证</a>在同一拍展开多个候选分支，兄弟分支的键在注意力里必须互相不可见——掩码之外，物理上还得各住各的暂存页。</p><p><span class="marginnote">直觉类比：投机解码像口译员抢话——先替发言人把三句翻出来，对方点头几句就采纳几句。缓存侧的麻烦在于：抢先翻的那几句已经写进了会议纪要，摇头之后必须擦干净，否则纪要里就永远留着没说过的话。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>提交协议</strong>。把「写入」与「生效」拆开。草稿位置的 KV 写进暂存页并打上候选标记；校验后按接受长度 \\(\\tau\\) 把前 \\(\\tau\\) 个位置的页转正、块表前进 \\(\\tau\\)，尾巴页原子释放。两条纪律：释放必须幂等（同一拍可能重复触发）；垃圾页不立即回发（沿用第一课的所有权——先改块表再动内存，池子的空闲表晚一拍更新无害）。</p><p><strong>峰值预算</strong>。上一课的并发上限乘峰值因子 \\((1+\\gamma)\\)，再按接受长度分布的 p99 而不是均值留余；接受长度进监控分位数，与 <a href="/llm/serving-metrics">TTFT/TPOT 口径</a>并列。</p><p><span class="marginnote">数字实例：\\(\\gamma=4\\)、每 token 128 KiB 时，校验一拍每条请求多挂 \\(4 \\times 128 = 512\\) KiB 暂存，100 并发就是约 50 MiB 额外峰值。接受长度若均值只有 1.5、p99 却到 4，按均值编预算的池子会在最忙的一拍撞墙——所以余量按 p99 留。</span></p><p><strong>树分支</strong>。祖先路径共享物理页直到分叉点，兄弟分支各持暂存页；接受路径转正为主干，其余整枝回滚。树越宽，一拍的峰值页数越多——树宽与批量的乘积才是真正的预算压力。</p>',11)),(e(),B(r,null,{default:a(()=>[n(A,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DRAFT%5B%22%E8%8D%89%E7%A8%BF%EF%BC%9A%E7%8C%9C%20%CE%B3%20%E4%B8%AA%20token%22%5D%20--%3E%20TMP%5B%22KV%20%E5%86%99%E5%85%A5%E6%9A%82%E5%AD%98%E9%A1%B5%EF%BC%8C%E6%89%93%E5%80%99%E9%80%89%E6%A0%87%E8%AE%B0%22%5D%0A%20%20TMP%20--%3E%20VER%7B%22%E7%9B%AE%E6%A0%87%E5%B9%B6%E8%A1%8C%E6%A0%A1%E9%AA%8C%22%7D%0A%20%20VER%20--%3E%7C%22%E5%89%8D%20%CF%84%20%E4%B8%AA%E6%8E%A5%E5%8F%97%22%7C%20COMMIT%5B%22%E5%9D%97%E8%A1%A8%E5%A2%9E%E9%95%BF%20%CF%84%EF%BC%8C%E9%A1%B5%E8%BD%AC%E6%AD%A3%22%5D%0A%20%20VER%20--%3E%7C%E6%8B%92%E7%BB%9D%7C%20RB%5B%22%E5%B0%BE%E9%83%A8%E6%9A%82%E5%AD%98%E9%A1%B5%E5%8E%9F%E5%AD%90%E9%87%8A%E6%94%BE%22%5D%0A%20%20COMMIT%20--%3E%20SHARE%7B%22%E6%8E%A5%E5%8F%97%E6%AE%B5%E6%8C%82%E5%89%8D%E7%BC%80%E6%A0%91%22%7D%0A%20%20SHARE%20--%3E%7C%E6%98%AF%7C%20CACHE%5B%22%E8%BF%9B%E5%85%B1%E4%BA%AB%E9%93%BE%EF%BC%8C%E8%AE%A1%E6%95%B0%E5%8A%A0%E4%B8%80%22%5D%0A%20%20SHARE%20--%3E%7C%E5%90%A6%7C%20NEXT%5B%22%E4%BB%85%E6%9C%AC%E8%AF%B7%E6%B1%82%E5%8F%AF%E8%A7%81%22%5D%0A%20%20RB%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E6%AD%A5%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<p><strong>与缓存链的接口</strong>。暂存页永远不进<a href="/llm/kv-prefix-cache">前缀共享链</a>——未接受的候选不是事实；接受段转正后才可被后续请求共享，指纹按转正后的形状算。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无损的兑现点在提交协议：算法保证「接受路径上的分布与目标一致」，协议保证「缓存里只存在被接受路径上的键」。两者缺一，系统级的输出分布仍会漂。带宽账同样被重写：接受长度 \\(\\tau\\) 使这一步读 \\(\\mathrm{KV}(n)+\\tau\\cdot c_{\\rm kv}\\) 的字节、省掉 \\(\\tau-1\\) 步；decode 本是<a href="/llm/arithmetic-intensity-decode">瘦计算胖加载</a>，多扫 \\(\\tau\\) 个位置的边际带宽几乎免费，这正是投机与带宽墙天然互补的原因。但互补有边界：批量加大后算力逐渐打满，「稍胖一次前向」不再免费，<a href="/llm/eagle">EAGLE</a>、<a href="/llm/medusa">Medusa</a> 一类自投机的树宽也要跟着批量收——收益递减时，KV 侧的峰值方差却在照付。</p><p><span class="marginnote">术语翻译：「提交协议」就是把「先写了」和「算数了」拆成两件事的簿记规则——草稿的键值先进暂存区挂个「候选」标签，等校验点头后才把标签换成「生效」。没有这道手续，缓存里就分不清哪些数字是事实、哪些只是猜测。</span></p>',4)),(e(),B(r,null,{default:a(()=>[n(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E8%8D%89%E7%A8%BF%20%CE%B3%20%E4%B8%AA%20token%2C%20KV%20%E5%85%88%E5%86%99%E8%BF%9B%E6%9A%82%E5%AD%98%E9%A1%B5%22%5D%20--%3E%20V%7B%22%E7%9B%AE%E6%A0%87%E6%A8%A1%E5%9E%8B%E5%B9%B6%E8%A1%8C%E6%A0%A1%E9%AA%8C%22%7D%0A%20%20V%20--%3E%7C%22%E5%89%8D%20%CF%84%20%E4%B8%AA%E6%8E%A5%E5%8F%97%22%7C%20C%5B%22%E5%9D%97%E8%A1%A8%E5%89%8D%E8%BF%9B%20%CF%84%2C%20%E8%BF%99%E6%AE%B5%E5%89%8D%E7%BC%80%E7%94%9F%E6%95%88%22%5D%0A%20%20V%20--%3E%7C%22%E5%85%B6%E4%BD%99%E6%8B%92%E7%BB%9D%22%7C%20R%5B%22%E5%B0%BE%E5%B7%B4%E6%9A%82%E5%AD%98%E9%A1%B5%E5%8E%9F%E5%AD%90%E9%87%8A%E6%94%BE%22%5D%0A%20%20R%20--%3E%20X%7B%22%E9%87%8A%E6%94%BE%E5%B9%B2%E5%87%80%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20X%20--%3E%7C%22%E6%B2%A1%E5%B9%B2%E5%87%80%22%7C%20L%5B%22%E8%A2%AB%E6%8B%92%E7%9A%84%E9%94%AE%E4%BB%8D%E6%8C%82%E5%9C%A8%E5%9D%97%E8%A1%A8%E4%B8%8A%22%5D%0A%20%20L%20--%3E%20N%5B%22%E4%B8%8B%E4%B8%80%E6%AD%A5%20attention%20%E6%89%AB%E5%88%B0%E5%AE%83%E4%BB%AC%22%5D%0A%20%20N%20--%3E%20W%5B%22%E6%A8%A1%E5%9E%8B%E7%9C%8B%E8%A7%81%E4%B8%8D%E5%AD%98%E5%9C%A8%E7%9A%84%20token%2C%20%E5%88%86%E5%B8%83%E6%BC%82%E7%A7%BB%22%5D%0A%20%20X%20--%3E%7C%22%E5%B9%B2%E5%87%80%22%7C%20OK%5B%22%E7%BC%93%E5%AD%98%E9%87%8C%E5%8F%AA%E5%89%A9%E4%BA%8B%E5%AE%9E%2C%20%E6%97%A0%E6%8D%9F%E6%89%BF%E8%AF%BA%E5%85%91%E7%8E%B0%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<p><span class="marginnote">监控里要有一个独立指标：每拍接受长度 \\(\\tau\\) 的分布。它同时是草稿质量、预算峰值与吞吐期望的充分统计；只报「加速比」会在批量或负载变化时掩盖池子压力的真实来源。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>回滚成本与页粒度耦合：\\(\\gamma\\) 个草稿位跨页时，尾巴释放会把还活跃的槽一起让出，实现要按槽而不是按页回收。流式输出必须「验证到哪提交到哪」，未验证的草稿不能进可见流。被抢占请求恢复时，暂存页一律作废重猜——保留半拍草稿状态的成本高于收益。多请求共享批时，各请求接受长度不同，批次内块表参差，核要支持变长而非补齐到最大（与<a href="/llm/splitfuse">混合批次</a>同一类约束）。最后，别把投机收益写进稳态容量规划：它是延迟优化，不是容量优化，池子的预算按峰值编。</p><p><span class="marginnote">常见误区：把投机解码的加速比写进容量规划。它省的是步数不是字节——峰值期池子反而要多养 \\(\\gamma\\) 份暂存，收益还随批量增大递减。容量按「没有投机」的稳态编，加速是延迟红利，不是容量余粮。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>被拒草稿的 KV 是污染源：下一步会 attend 到它，无损性必须在提交协议里兑现，不只是算法里。</li><li>写入与生效分离：暂存页 + 候选标记 + 按接受长度原子转正/释放。</li><li>预算按峰值编：并发上限乘 \\((1+\\gamma)\\)，接受长度分布按 p99 留余。</li><li>树分支祖先共享、兄弟隔离；暂存页永不进前缀共享链。</li><li>投机与带宽墙互补，但收益随批量递减；监控独立报接受长度分布。</li><li>出处：Leviathan et al., ICML 2023；Miao et al., SpecInfer, OSDI 2024；树验证口径据本仓库投机解码课序。</li></ul>',6))])}const f=i(p,[["render",m]]);export{_ as __pageData,f as default};
